def validate_transaction(node, cache=None):
    if cache is None:
        cache = {}

    if node is None or not node.is_valid:  # Check if node is None or invalid
        return 0
    if node in cache:
        return cache[node]

    result = 1 + validate_transaction(node.left, cache) + validate_transaction(node.right, cache)
    cache[node] = result
    return result
